def transform(grid):
    from collections import Counter
    counts = Counter()
    h, w = len(grid), len(grid[0])
    for i in range(h - 1):
        for j in range(w - 1):
            a, b = grid[i][j], grid[i][j+1]
            c, d = grid[i+1][j], grid[i+1][j+1]
            if a != 0 and a == b == c == d:
                counts[a] += 1
    for k, v in counts.items():
        if v == 2:
            return [[0]]
    return [[1]]
